from redirect import build_absolute_next, sanitize_next_path


def build_post_login_redirect(next_param: str | None) -> str:
    """
    Decide where to send the browser after a successful login.

    `next_param` is taken from the query string. Only same-host relative paths
    or absolute URLs already on the product host are permitted.
    """
    if next_param is None:
        return build_absolute_next(None)
    text = next_param.strip()
    if not text:
        return build_absolute_next(None)
    if text.startswith("/") and not text.startswith("//"):
        return build_absolute_next(text)
    # BUG: passes through absolute off-site URLs instead of falling back to a safe default.
    if text.startswith("http://") or text.startswith("https://"):
        return text
    if text.startswith("//"):
        return text
    return build_absolute_next(text)


