from __future__ import annotations

from urllib.parse import parse_qsl, quote, urlencode, urlparse, urlunparse


def _default_allowed_hosts() -> set[str]:
    return {"app.example.com", "localhost", "127.0.0.1"}


def current_product_host() -> str:
    return "app.example.com"


def sanitize_next_path(raw: str | None, *, allowed_hosts: set[str] | None = None) -> str | None:
    """
    Return a safe path+query fragment for internal navigation, or None if unusable.

    Only relative paths starting with '/' are accepted. Absolute URLs are rejected.
    """
    if raw is None:
        return None
    text = raw.strip()
    if not text:
        return None
    if not text.startswith("/"):
        return None
    if "//" in text.split("?", 1)[0]:
        return None
    return text


def build_absolute_next(raw: str | None, *, default: str = "/home") -> str:
    """Build an absolute URL on the product host from a sanitized relative next."""
    host = current_product_host()
    safe = sanitize_next_path(raw) or default
    parsed = urlparse(f"https://{host}{safe}")
    return urlunparse(("https", host, parsed.path or "/", "", parsed.query, ""))


